def box_uniform_border(g,a,b,c,d):
    s=set(g[a][c:d+1])|set(g[b][c:d+1])|{g[r][c] for r in range(a,b+1)}|{g[r][d] for r in range(a,b+1)}
    return len(s)==1

def find_frames_sorted(g, r0,r1,c0,c1):
    # greedy: repeatedly take largest-area rect inside with uniform border, strictly shrinking
    res=[]; a,b,c,d=r0,r1,c0,c1
    while True:
        cands=[]
        for A in range(a,b+1):
            for B in range(A,b+1):
                for C in range(c,d+1):
                    for D in range(C,d+1):
                        if B-A>=1 and D-C>=1 and box_uniform_border(g,A,B,C,D):
                            cands.append(((B-A+1)*(D-C+1),A,B,C,D))
        if not cands: break
        cands.sort(key=lambda x:-x[0])
        _,A,B,C,D=cands[0]
        col=g[A][C]
        res.append((col,A,B,C,D)); a,b,c,d=A,B,C,D
    return res

def f(grid):
    g=[r[:] for r in grid]; out=[r[:] for r in grid]
    seen=[[False]*len(g[0]) for _ in g]
    for i in range(len(g)):
        for j in range(len(g[0])):
            if g[i][j]!=0 and not seen[i][j]:
                comp=[]; st=[(i,j)]; seen[i][j]=True
                while st:
                    y,x=st.pop(); comp.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<len(g) and 0<=nx<len(g[0]) and g[ny][nx]!=0 and not seen[ny][nx]:
                            seen[ny][nx]=True; st.append((ny,nx))
                rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
                r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
                fr=find_frames_sorted(g,r0,r1,c0,c1)
                seq=[fr[k][0] for k in range(len(fr))]
                newseq=[seq[(k-1)%len(seq)] for k in range(len(seq))]
                for kk,(col,A,B,C,D) in enumerate(fr):
                    ncol=newseq[kk]
                    for x in range(C,D+1): out[A][x]=ncol; out[B][x]=ncol
                    for y in range(A,B+1): out[y][C]=ncol; out[y][D]=ncol
    return out

